const welcome=document.createElement('dialog');welcome.id='welcomeDialog';welcome.setAttribute('aria-labelledby','welcomeTitle');welcome.innerHTML=`<button class="close" id="skipWelcome" aria-label="Bỏ qua giới thiệu">×</button><div class="welcome-layout"><div class="welcome-art"><span class="hello-bubble">Xin chào! <span>✦</span></span><div class="welcome-orbit orbit-one"></div><div class="welcome-orbit orbit-two"></div><img src="assets/phi-phi-master-v1.png" alt="Phi Phi xanh ngọc mở tay chào bạn"/><span class="welcome-shadow"></span><span class="welcome-spark spark-one">✦</span><span class="welcome-spark spark-two">✧</span><span class="welcome-name">PHI PHI / TRẠM TEAM</span></div><div class="welcome-copy"><div class="eyebrow">CHÀO MỪNG ĐẾN TRẠM MARKETING</div><h2 id="welcomeTitle">Chào bạn,<br>mình là Phi Phi!</h2><p>Mời bạn ghé văn phòng. Đội ngũ của mình có <b>11 vai trò</b>, cùng phối hợp để đưa một brief qua từng bước làm việc.</p><div class="welcome-pills"><span>🌿 Một đội ngũ</span><span>◈ Nhiều dự án</span><span>✓ Bạn duyệt</span></div><button class="primary full" id="enterOffice">Vào văn phòng cùng Phi Phi →</button><p class="welcome-note">Đây là bản mô phỏng trực quan, chưa kết nối AI thật.</p></div></div>`;document.body.append(welcome);const closeWelcome=()=>{welcome.close();$('#newBrief').focus()};$('#enterOffice').onclick=closeWelcome;$('#skipWelcome').onclick=closeWelcome;const replay=document.createElement('button');replay.className='nav replay-welcome';replay.textContent='✦   Phi Phi chào bạn';replay.onclick=()=>welcome.showModal();document.querySelector('body>aside').insertBefore(replay,$('.side-bottom'));welcome.showModal();
